-- 콘텐츠 스냅샷: V1~V96을 이 시점의 로컬 DB 스키마+콘텐츠 데이터로 통합. 후원 결제(donation*)와 방문자 통계(visitor_*)는 운영 데이터 보존을 위해 스키마만 포함하고 데이터는 제외함.

SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE `architecture_layer` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `icon` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  `is_visible` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `architecture_layer_item` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `layer_id` bigint NOT NULL,
  `strong_text` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `body_text` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `fk_architecture_layer_item_layer` (`layer_id`),
  CONSTRAINT `fk_architecture_layer_item_layer` FOREIGN KEY (`layer_id`) REFERENCES `architecture_layer` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=83 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `architecture_overview` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `heading` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subheading` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `diagram_heading` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `diagram_text` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `career` (
  `experience_id` bigint NOT NULL,
  `company_name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `employment_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `department` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`experience_id`),
  CONSTRAINT `fk_career_experience` FOREIGN KEY (`experience_id`) REFERENCES `experience` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `certificate` (
  `experience_id` bigint NOT NULL,
  `issuer` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`experience_id`),
  CONSTRAINT `fk_certificate_experience` FOREIGN KEY (`experience_id`) REFERENCES `experience` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competency` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  `is_visible` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competency_evidence` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `competency_id` bigint NOT NULL,
  `experience_id` bigint NOT NULL,
  `evidence_summary` varchar(700) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_primary` tinyint(1) NOT NULL DEFAULT '0',
  `display_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competency_evidence` (`competency_id`,`experience_id`),
  KEY `fk_competency_evidence_experience` (`experience_id`),
  CONSTRAINT `fk_competency_evidence_competency` FOREIGN KEY (`competency_id`) REFERENCES `competency` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_competency_evidence_experience` FOREIGN KEY (`experience_id`) REFERENCES `experience` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competency_skill` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `competency_id` bigint NOT NULL,
  `skill_id` bigint NOT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competency_skill` (`competency_id`,`skill_id`),
  KEY `fk_competency_skill_skill` (`skill_id`),
  CONSTRAINT `fk_competency_skill_competency` FOREIGN KEY (`competency_id`) REFERENCES `competency` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_competency_skill_skill` FOREIGN KEY (`skill_id`) REFERENCES `skill` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=200 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competency_study` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `competency_id` bigint NOT NULL,
  `study_id` bigint NOT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competency_study` (`competency_id`,`study_id`),
  KEY `fk_competency_study_study` (`study_id`),
  CONSTRAINT `fk_competency_study_competency` FOREIGN KEY (`competency_id`) REFERENCES `competency` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_competency_study_study` FOREIGN KEY (`study_id`) REFERENCES `study` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=330 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `donation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `client_token` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` int NOT NULL,
  `currency` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'KRW',
  `message` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mul_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pay_state` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_subscription` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime(6) NOT NULL,
  `paid_at` datetime(6) DEFAULT NULL,
  `provider_paid_at` datetime(6) DEFAULT NULL,
  `canceled_at` datetime(6) DEFAULT NULL,
  `version` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_donation_client_token` (`client_token`),
  UNIQUE KEY `uk_donation_mul_no` (`mul_no`),
  KEY `idx_donation_status_created` (`status`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `donation_event` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `donation_id` bigint NOT NULL,
  `event_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `actor` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pay_state` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `detail` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_donation_event_donation` (`donation_id`),
  CONSTRAINT `fk_donation_event_donation` FOREIGN KEY (`donation_id`) REFERENCES `donation` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `donation_setting` (
  `id` bigint NOT NULL,
  `donation_enabled` tinyint(1) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `education` (
  `experience_id` bigint NOT NULL,
  `institution_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`experience_id`),
  CONSTRAINT `fk_education_experience` FOREIGN KEY (`experience_id`) REFERENCES `experience` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `experience` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `type` varchar(31) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `period_start` date NOT NULL,
  `period_end` date DEFAULT NULL,
  `summary` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `takeaway` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  `show_on_timeline` tinyint(1) NOT NULL DEFAULT '1',
  `timeline_label` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `experience_detail` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `experience_id` bigint DEFAULT NULL,
  `content` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  `situation` text COLLATE utf8mb4_unicode_ci,
  `task` text COLLATE utf8mb4_unicode_ci,
  `action_detail` text COLLATE utf8mb4_unicode_ci,
  `outcome` text COLLATE utf8mb4_unicode_ci,
  `narrative` text COLLATE utf8mb4_unicode_ci,
  `visible` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `fk_exp_detail_experience` (`experience_id`),
  CONSTRAINT `fk_exp_detail_experience` FOREIGN KEY (`experience_id`) REFERENCES `experience` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `experience_detail_skill` (
  `experience_detail_id` bigint NOT NULL,
  `skill_id` bigint NOT NULL,
  `list_order` int NOT NULL,
  PRIMARY KEY (`experience_detail_id`,`list_order`),
  KEY `fk_exp_detail_skill_skill` (`skill_id`),
  CONSTRAINT `fk_exp_detail_skill_detail` FOREIGN KEY (`experience_detail_id`) REFERENCES `experience_detail` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_exp_detail_skill_skill` FOREIGN KEY (`skill_id`) REFERENCES `skill` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `experience_image` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `experience_id` bigint DEFAULT NULL,
  `object_key` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_experience_image_experience_id` (`experience_id`),
  CONSTRAINT `fk_experience_image_experience` FOREIGN KEY (`experience_id`) REFERENCES `experience` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `experience_placement` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `experience_id` bigint NOT NULL,
  `placement_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  `enabled` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_experience_placement` (`experience_id`,`placement_type`),
  KEY `idx_experience_placement_public` (`placement_type`,`enabled`,`display_order`),
  CONSTRAINT `fk_experience_placement_experience` FOREIGN KEY (`experience_id`) REFERENCES `experience` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `experience_placement_detail` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `placement_id` bigint NOT NULL,
  `experience_detail_id` bigint NOT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_experience_placement_detail` (`placement_id`,`experience_detail_id`),
  KEY `fk_placement_detail_experience_detail` (`experience_detail_id`),
  KEY `idx_placement_detail_order` (`placement_id`,`display_order`),
  CONSTRAINT `fk_placement_detail_experience_detail` FOREIGN KEY (`experience_detail_id`) REFERENCES `experience_detail` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_placement_detail_placement` FOREIGN KEY (`placement_id`) REFERENCES `experience_placement` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `experience_relation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `source_experience_id` bigint NOT NULL,
  `target_experience_id` bigint NOT NULL,
  `relation_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_experience_relation` (`source_experience_id`,`target_experience_id`,`relation_type`),
  KEY `idx_experience_relation_target` (`target_experience_id`),
  CONSTRAINT `fk_experience_relation_source` FOREIGN KEY (`source_experience_id`) REFERENCES `experience` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_experience_relation_target` FOREIGN KEY (`target_experience_id`) REFERENCES `experience` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_experience_relation_not_self` CHECK ((`source_experience_id` <> `target_experience_id`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `experience_skill` (
  `experience_id` bigint NOT NULL,
  `skill_id` bigint NOT NULL,
  `list_order` int NOT NULL,
  PRIMARY KEY (`experience_id`,`list_order`),
  KEY `fk_exp_skill_skill` (`skill_id`),
  CONSTRAINT `fk_exp_skill_experience` FOREIGN KEY (`experience_id`) REFERENCES `experience` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_exp_skill_skill` FOREIGN KEY (`skill_id`) REFERENCES `skill` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `experience_tag` (
  `experience_id` bigint NOT NULL,
  `tag_id` bigint NOT NULL,
  PRIMARY KEY (`experience_id`,`tag_id`),
  KEY `fk_experience_tag_tag` (`tag_id`),
  CONSTRAINT `fk_experience_tag_experience` FOREIGN KEY (`experience_id`) REFERENCES `experience` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_experience_tag_tag` FOREIGN KEY (`tag_id`) REFERENCES `tag` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `print_template` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `excluded_ids` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `section_order` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `section_gaps` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_role` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GENERAL',
  `content_overrides` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `base_content_fingerprint` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `schema_version` int NOT NULL DEFAULT '2',
  `visible` tinyint(1) NOT NULL DEFAULT '1',
  `display_order` int NOT NULL DEFAULT '0',
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `profile` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `job_title` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `bio` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `core_stack_summary` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status_badge_text` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `github_url` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `project` (
  `experience_id` bigint NOT NULL,
  `career_experience_id` bigint DEFAULT NULL,
  `slug` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `contribution_rate` int DEFAULT NULL,
  `repository_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`experience_id`),
  KEY `idx_project_career` (`career_experience_id`),
  CONSTRAINT `fk_project_career` FOREIGN KEY (`career_experience_id`) REFERENCES `career` (`experience_id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_project_experience` FOREIGN KEY (`experience_id`) REFERENCES `experience` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `skill` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `skill_level` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_core` tinyint(1) NOT NULL DEFAULT '0',
  `display_order` int NOT NULL DEFAULT '0',
  `skill_version` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `skill_comment` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `usage_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'LEARNING',
  `badge_key` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `badge_color` varchar(6) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `study` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `slug` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_markdown` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category_id` bigint NOT NULL,
  `learned_at` date NOT NULL,
  `published_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_study_status_learned_at` (`status`,`learned_at`),
  KEY `idx_study_category_id` (`category_id`),
  CONSTRAINT `fk_study_category` FOREIGN KEY (`category_id`) REFERENCES `study_category` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `study_category` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `study_entry` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(1200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `takeaway` varchar(800) COLLATE utf8mb4_unicode_ci NOT NULL,
  `learned_at` date NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `study_entry_skill` (
  `study_entry_id` bigint NOT NULL,
  `skill` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  KEY `fk_study_entry_skill_study_entry` (`study_entry_id`),
  CONSTRAINT `fk_study_entry_skill_study_entry` FOREIGN KEY (`study_entry_id`) REFERENCES `study_entry` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `study_experience` (
  `study_id` bigint NOT NULL,
  `experience_id` bigint NOT NULL,
  PRIMARY KEY (`study_id`,`experience_id`),
  KEY `fk_study_experience_experience` (`experience_id`),
  CONSTRAINT `fk_study_experience_experience` FOREIGN KEY (`experience_id`) REFERENCES `experience` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_study_experience_study` FOREIGN KEY (`study_id`) REFERENCES `study` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `study_experience_detail` (
  `study_id` bigint NOT NULL,
  `experience_detail_id` bigint NOT NULL,
  PRIMARY KEY (`study_id`,`experience_detail_id`),
  KEY `fk_study_experience_detail_detail` (`experience_detail_id`),
  CONSTRAINT `fk_study_experience_detail_detail` FOREIGN KEY (`experience_detail_id`) REFERENCES `experience_detail` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_study_experience_detail_study` FOREIGN KEY (`study_id`) REFERENCES `study` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `study_image` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `study_id` bigint DEFAULT NULL,
  `object_key` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_study_image_study_id` (`study_id`),
  CONSTRAINT `fk_study_image_study` FOREIGN KEY (`study_id`) REFERENCES `study` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `study_relation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `source_study_id` bigint NOT NULL,
  `target_study_id` bigint NOT NULL,
  `relation_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_study_relation` (`source_study_id`,`target_study_id`,`relation_type`),
  KEY `fk_study_relation_target` (`target_study_id`),
  CONSTRAINT `fk_study_relation_source` FOREIGN KEY (`source_study_id`) REFERENCES `study` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_study_relation_target` FOREIGN KEY (`target_study_id`) REFERENCES `study` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=161 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `study_skill` (
  `study_id` bigint NOT NULL,
  `skill_id` bigint NOT NULL,
  PRIMARY KEY (`study_id`,`skill_id`),
  KEY `fk_study_skill_skill` (`skill_id`),
  CONSTRAINT `fk_study_skill_skill` FOREIGN KEY (`skill_id`) REFERENCES `skill` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_study_skill_study` FOREIGN KEY (`study_id`) REFERENCES `study` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `study_tag` (
  `study_id` bigint NOT NULL,
  `tag_id` bigint NOT NULL,
  PRIMARY KEY (`study_id`,`tag_id`),
  KEY `fk_study_tag_tag` (`tag_id`),
  CONSTRAINT `fk_study_tag_study` FOREIGN KEY (`study_id`) REFERENCES `study` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_study_tag_tag` FOREIGN KEY (`tag_id`) REFERENCES `tag` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `tag` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `visitor_daily_visit` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `visitor_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `visited_date` date NOT NULL,
  `first_visited_at` datetime(6) NOT NULL,
  `last_visited_at` datetime(6) NOT NULL,
  `page_views` bigint NOT NULL DEFAULT '1',
  `user_agent` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_bot` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_visitor_daily_visit_hash_date` (`visitor_hash`,`visited_date`),
  KEY `idx_visitor_daily_visit_date` (`visited_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `visitor_hourly_visit` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `visitor_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `visited_date` date NOT NULL,
  `visited_hour` int NOT NULL,
  `page_views` bigint NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_visitor_hourly_visit_hash_date_hour` (`visitor_hash`,`visited_date`,`visited_hour`),
  KEY `idx_visitor_hourly_visit_date` (`visited_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `architecture_layer` (`id`, `icon`, `title`, `display_order`, `is_visible`, `created_at`, `updated_at`) VALUES (1,'💻','Backend Layer',1,1,'2026-07-16 05:15:59','2026-07-16 05:15:59'),(2,'🎨','Frontend Layer',2,1,'2026-07-16 05:15:59','2026-07-21 23:26:10'),(3,'☸️','DevOps & GitOps',4,1,'2026-07-16 05:15:59','2026-07-21 23:26:34'),(4,'🗄️','Database & Data Management',3,1,'2026-07-16 05:35:09','2026-07-16 14:45:20');
INSERT INTO `architecture_layer_item` (`id`, `layer_id`, `strong_text`, `body_text`, `display_order`) VALUES (66,1,'Java 21 & Spring Boot 3.5',': ai·architecture·competency·donation·experience·printtemplate·profile·skill·storage·visitor·study까지 11개 도메인 모듈로 분리해 구축',0),(67,1,'Spring Security 세션 인증',': /api/admin/**를 ROLE_ADMIN 전용으로 제한하고 공개 GET은 화이트리스트로 개방, CSRF 쿠키 필터 적용',1),(68,1,'Spring Data JPA & QueryDSL','로 동적 검색·필터링 쿼리를 타입 세이프하게 처리',2),(69,1,'NVIDIA NIM 기반 AI 초안 생성',': competency·experience·study 3개 모듈이 공용 LLM 클라이언트를 쓰되 도메인별 기능 플래그로 독립 on/off, SSE 스트리밍 지원',3),(70,1,'Ko-fi 웹훅 후원 결제',': verification-token 검증과 거래 ID 단위 락으로 중복 반영을 막고 다통화·구독 후원을 지원',4),(71,2,'Next.js 16 (App Router) & React 19 & TypeScript',': (public)/admin 라우트 그룹으로 공개 페이지와 관리자 CMS를 분리',0),(72,2,'Zustand & TanStack Query','를 조합한 프론트 전역 상태 및 비동기 API 캐시 제어',1),(73,2,'브라우저 완결형 인쇄/PDF 내보내기',': 섹션·스킬 선택 → 페이지 분할 계산 → 서버 템플릿 저장까지 클라이언트에서 처리, 별도 PDF 렌더 서버 없음',2),(74,2,'관리자 CMS 연동 API 클라이언트',': profile·skill·experience·study·competency·architecture·donation·visitor 등 전체 콘텐츠를 관리자 화면에서 실시간 편집',3),(75,3,'GitHub Actions & OCIR',': 백엔드·프론트엔드 각각 ARM64 네이티브 이미지를 빌드해 Oracle OCI Registry에 배포하고 Kustomize 이미지 태그를 main에 재커밋',0),(76,3,'ArgoCD 자동 동기화',': backend/frontend 두 Application이 각각 auto-sync·prune·self-heal로 OKE 클러스터에 무중단 반영',1),(77,3,'Sealed Secrets 분리 암호화',': DB·AI(NVIDIA API 키)·Ko-fi·Storage 자격증명을 각각 비대칭 키로 암호화해 Git에 안심하고 형상 관리',2),(78,3,'Cloudflare + Ingress Nginx 단일 진입점',': unbrdn.me/www.unbrdn.me(프론트)와 api.unbrdn.me(백엔드) 모두 Origin CA 인증서를 쓰는 동일 ingress 뒤에서 서빙, SSE 스트리밍을 위한 프록시 버퍼링 해제 설정 포함',3),(79,4,'Flyway 마이그레이션 65개 버전','으로 V1 초기 스키마부터 이 페이지의 콘텐츠 갱신(V66)까지 스키마 변경 이력을 전부 추적',0),(80,4,'MySQL HeatWave Always Free(운영) / MySQL 8.0 컨테이너(로컬) 이원화',': 로컬은 JPA_DDL_AUTO=update, 운영은 Flyway 단독으로 스키마 변경을 엄격히 통제',1),(81,4,'프로필·스킬·경력·역량·Study·아키텍처·후원 전 콘텐츠의 DB 관리',': 지금 보고 있는 이 페이지도 하드코딩이 아니라 관리자 화면에서 편집하는 DB 콘텐츠',2),(82,4,'Oracle Object Storage(운영) / MinIO(로컬) S3 호환 스토리지',': Presigned URL 발급 후 브라우저가 직접 업로드하고 DB에는 objectKey만 저장',3);
INSERT INTO `architecture_overview` (`id`, `heading`, `subheading`, `diagram_heading`, `diagram_text`, `updated_at`) VALUES (1,'시스템 아키텍처 (Self-Intro Architecture)','이 포트폴리오 웹앱의 11개 도메인 모듈로 나뉜 백엔드, Next.js 프론트엔드, 도메인별로 격리된 LLM 콘텐츠 생성과 Ko-fi 후원 연동, 그리고 Kubernetes·ArgoCD 기반 GitOps 배포 인프라까지 담은 설계 명세입니다.','실제 운영(Production) 시스템 아키텍처 및 배포 흐름도',' +-----------------------------------------------------------------------------------------+\n |                                    [ Web Client User ]                                  |\n |                                             |                                           |\n |         https://unbrdn.me, www.unbrdn.me    |    https://api.unbrdn.me                 |\n |                     +-----------------------+-----------------------+                   |\n |                     |                                               |                   |\n |                     v                                               v                   |\n |           [ Cloudflare DNS Proxy + Origin CA TLS ]  <-------------------------------->  |\n |                                             |                                           |\n |                                             | OCI Load Balancer                         |\n |                                             v                                           |\n |                              [ Ingress Nginx Controller ]                               |\n |                            SSL/TLS Route, SSE proxy-buffering off                       |\n |  +-----------------------------------------------------------------------------------+  |\n |  |                          Oracle Kubernetes Engine (OKE Cluster)                   |  |\n |  |                                                                                   |  |\n |  |   [ Argo CD (backend / frontend Applications) ]   [ Sealed Secrets Controller ]   |  |\n |  |     - Watches GitHub repo, auto sync/prune/self-heal - Decrypts DB/AI/Ko-fi/      |  |\n |  |                    |                                    Storage secrets           |  |\n |  |                    v                                          |                   |  |\n |  |   +---------------------------+     +---------------------------+                 |  |\n |  |   | [ self-intro-frontend ]   |     | [ self-intro-backend ]     |                 |  |\n |  |   |  Next.js 16 (App Router)  |     |  Spring Boot 3.5 (Java 21) |                 |  |\n |  |   |  ARM64 pod, port 3000     |     |  ARM64 pod, port 8080      |                 |  |\n |  |   +---------------------------+     +--------------|-------------+                 |  |\n |  +------------------------------------------------------|--------------------------------+  |\n |                                                          | JDBC (OCI VCN Private Subnet)     |\n |                                                          v                                   |\n |                                   [ MySQL HeatWave Database (Always Free) ]                  |\n |                                     - Flyway가 관리하는 스키마, 65개 버전 이력                   |\n |                                                          |                                    |\n |                              +---------------------------+----------------------------+       |\n |                              v                                                        v       |\n |                [ NVIDIA NIM (외부 LLM API) ]                       [ OCI Object Storage (S3 호환) ]\n |                  Spring AI 경유, 도메인별 기능 플래그로 격리              Presigned URL 업로드\n |                                                                                                |\n |                              ^                                                                 |\n |                              | Webhook (verification-token 검증)                               |\n |                       [ Ko-fi 후원 결제 ]                                                       |\n +-----------------------------------------------------------------------------------------+','2026-07-21 23:26:36');
INSERT INTO `career` (`experience_id`, `company_name`, `employment_type`, `department`, `role`) VALUES (1,'수학에 심장을 달다','정규직','개발팀 백엔드 파트','Backend Engineer');
INSERT INTO `certificate` (`experience_id`, `issuer`) VALUES (10,'한국산업인력공단'),(11,'(재)한국데이터산업진흥원'),(12,'(재)한국데이터산업진흥원'),(13,'대한상공회의소');
INSERT INTO `competency` (`id`, `title`, `summary`, `display_order`, `is_visible`, `created_at`, `updated_at`) VALUES (1,'서로 다른 요구를 하나의 구조로 통합하는 추상화 감각','CS 통합 페이지는 전형적인 3계층 대신 auth·file·inquiry 기능 단위로 api·domain·repository·usecase를 나누는 수직 슬라이스 구조를 택하고, 웹훅 수신과 후속 처리를 Spring 이벤트로 분리했습니다. 포트폴리오 서버에서도 응답용 타입과 폼 전송용 타입을 API 계약 단계에서부터 갈라 두어, 화면 요구가 바뀌어도 서로 영향을 주지 않게 설계합니다.',2,1,'2026-07-15 12:04:21','2026-07-24 13:11:15'),(2,'무중단으로 리스크 있는 변경을 완수하는 실행력','실서비스 데이터가 쌓인 상태에서 PII 암호화를 도입하며 \"이미 공개된 데이터인지, 진짜 고객 개인정보인지\"를 기준으로 암호화 범위를 판단해 과잉 암호화를 피했습니다. 앱 기동 시 함께 실행되던 마이그레이션 로직을 별도 CLI 도구로 분리하는 과정에서 실제 240건 이관을 직접 돌려보며 NULL 데이터로 인한 오류를 찾아 그 자리에서 고쳤습니다.',6,0,'2026-07-15 12:04:21','2026-07-24 13:11:15'),(3,'프로토콜을 지키며 장애를 흡수하는 방어적 통합 설계','카카오 챗봇 규격이 요구하는 HTTP 200 응답을 지키면서도 가상 스레드로 4.5초 내부 타임아웃을 걸어, 지연되면 정중한 안내 메시지로 대체합니다. 클라우드 진단 에이전트는 인증이 403으로 실패하면 자격 증명을 폐기 후 재발급하고, 권한 전파 지연은 지수 백오프로 흡수하며 원격 킬스위치로 즉시 중단할 수 있게 설계했습니다. 포트폴리오 서버에서도 공용 AI 클라이언트를 도메인별 독립 플래그로 격리해 장애 영향 범위를 좁혔습니다.',5,0,'2026-07-15 12:04:21','2026-07-24 13:11:15'),(4,'증상이 아니라 근본 원인까지 쫓아 재발을 막는 진단력','포트폴리오 서버의 인쇄 기능에서 편집 모드와 미리보기 화면의 치수가 미세하게 어긋나는 문제를 폰트 상속, 컴포넌트 스코프 같은 근본 원인까지 하나씩 좁혀가며 18차례의 연속 커밋으로 완전히 해결했습니다. Azure 리소스 진단과 사내 CS 시스템에서도 증상 로그가 아니라 원인 데이터를 근거로 진단 규칙과 관측 파이프라인을 직접 설계해 재발을 막습니다.',4,1,'2026-07-15 12:04:21','2026-07-24 13:11:15'),(5,'LLM을 판단 흐름에 결합하며 비용과 신뢰성까지 설계하는 능력','진단 결과를 LLM에 결합해 실행 가능한 처방 카드를 자동 생성하는 동시에, tiktoken으로 토큰을 실측해 규칙별로 배치 요청하고 프롬프트를 캐싱해 API 비용과 응답 속도를 함께 통제했습니다. 이력서 RAG 파이프라인은 Rerank로 근거 정확도를 높였고, 포트폴리오 서버는 동기 응답과 SSE 스트리밍을 함께 지원해 생성 시간에 따라 사용자 경험을 조절합니다.',7,0,'2026-07-15 12:04:21','2026-07-24 13:11:15'),(6,'요구 파악부터 배포·운영까지 혼자 완결하는 오너십','카카오 챗봇 스킬 서버까지 포함한 4개 채널의 CS 통합 페이지를 기획자·인프라팀 없이 혼자 설계·배포했고, 무료체험 백오피스도 요구사항 정의부터 알림 연동, 운영 이슈 대응까지 책임졌습니다. 개인 포트폴리오 서버 역시 기획·개발·인프라·GitOps 배포까지 전 과정을 혼자 운영하고 있습니다.',1,1,'2026-07-19 19:19:23','2026-07-24 13:11:15'),(8,'문제가 터지기 전에 조회 결함을 예측해 막는 설계 습관','생성 시각 기반인 UUIDv7 ID만으로 커서 페이지네이션을 짜면 백필된 데이터의 순서가 뒤틀릴 수 있다는 점을 코드 작성 시점에 미리 인지하고 (시각, ID) 복합 커서로 설계했습니다. 프로모션-옵션처럼 연관 데이터를 함께 읽어야 하는 조회는 EntityGraph로 N+1을 사전에 차단했습니다.',3,1,'2026-07-24 03:42:56','2026-07-24 13:11:15'),(9,'협업 프로젝트에서 내 역할의 경계를 명확히 나누고 증명하는 방식','3인이 함께한 클라우드 진단 플랫폼에서 진단 규칙 엔진은 팀원과 함께 만들었지만, 오케스트레이션과 배포 파이프라인은 커밋 기준으로 제가 주도해 기여도를 코드 경계로 설명할 수 있습니다. 학습 플랫폼에서도 \"Feedback:\" 접두사를 단 리뷰 코멘트를 1,100건 넘게 남기고 반영하며 PR 기반으로 검증하는 협업 방식을 지켰습니다.',8,0,'2026-07-24 03:42:56','2026-07-24 13:11:15'),(10,'완벽한 커버리지보다 회귀 위험을 정확히 겨냥하는 테스트 전략','CS 통합 페이지는 테스트가 3개 클래스뿐이지만 \"운영자 답장이 문의로 재수집되는 무한루프\", \"해결된 티켓의 자동 재오픈\" 같은 실제 회귀 위험 지점만 정확히 겨냥해 작성했습니다. 포트폴리오 서버는 웹훅 멱등성과 AI 폴백 계약을 13개 테스트로 검증하되 프런트엔드는 타입 체크로 대체하는 등, 프로젝트 성격에 따라 테스트 투자 지점을 다르게 판단합니다.',9,0,'2026-07-24 03:42:56','2026-07-24 13:11:15'),(11,'과장 없이 근거를 스스로 감사하는 태도','이 포트폴리오의 경력·프로젝트 콘텐츠는 실제 커밋과 코드를 다시 감사해, 확인되지 않거나 부풀려진 주장을 의도적으로 제외하고 재작성한 결과입니다. 마이그레이션 커밋에 무엇을 근거로 남기고 무엇을 뺐는지 \"증거 경계\"를 직접 기록해, 근거 없는 성과보다 확인 가능한 사실만 남기는 것을 원칙으로 삼습니다.',10,0,'2026-07-24 03:42:56','2026-07-24 13:11:15');
