INSERT INTO `education` (`experience_id`, `institution_name`) VALUES (6,'차의과학대학교'),(7,'Microsoft / 대한상공회의소'),(8,'SBA 청년취업사관학교'),(9,'멀티캠퍼스');
INSERT INTO `experience` (`id`, `type`, `title`, `period_start`, `period_end`, `summary`, `takeaway`, `display_order`, `show_on_timeline`, `timeline_label`) VALUES (1,'CAREER','에듀테크 학습 플랫폼 Backend Engineer','2023-12-01','2025-10-31','학생·교사·학원이 사용하는 커리큘럼 기반 학습 플랫폼에서 핵심 API, BFF, 사내 백오피스와 공용 서비스를 개발했습니다. 대표 애플리케이션 저장소 main 브랜치 9,521개 커밋 중 4,110개를 담당했으며, 자발적 백오피스 TF에서는 기획·디자인·프론트엔드·운영 담당자와 협업해 백엔드와 운영 인프라를 맡았습니다.','기능 구현에 그치지 않고 요구사항 조율, 반복 릴리스, 운영 이슈 대응, 공통 개발 기반 정리까지 제품 개발의 전 과정을 경험했습니다.',5,1,NULL),(2,'PROJECT','[청년 일경험] 고객문의 수집 및 CS 통합 관리 페이지 구현','2026-05-18','2026-07-10','청년 일경험 기회를 통해 2달 동안 실제 회사내에서 발생하는 CS 이력 관리 문제를 파악하여 데이터들을 관리할 수 있는 웹 기반 CS 통합 처리 페이지를 구현하여 여러 채널로 들어온 CS들을 하나의 플랫폼에서 관리할 수 있도록 구현했습니다.','여러 채널 (네이버 카페, 이메일, 구글폼)로 분산되어 있던 고객 문의 정보를 n8n을 통해 수집하여 회사 시스템의 DB에 적재하여 이력을 관리할 수 있게 되었습니다.\n\n또한, 데이터들을 관리할 수 있는 웹 기반 CS 통합 처리 페이지를 구현하여 여러 채널로 들어온 CS들을 하나의 플랫폼에서 관리할 수 있도록 구현했습니다. \n\n이로 인해 CS를 담당하시는 분들은 온전히 CS 처리 자체에 집중할 수 있게 되었습니다.\n\n개인적인 성과로는 Java, Spring Boot를 사용하는 경험을 얻을 수 있었고, 현실의 문제를 해결하는 소프트웨어를 정의하고 구현하는 경험을 얻을 수 있었습니다.',1,1,'일경험'),(3,'PROJECT','Azure 로그 비용·관측성 진단 플랫폼 (LogDoctor)','2026-03-01','2026-06-30','Azure 리소스의 로그 비용과 관측성 상태를 진단하는 팀 프로젝트입니다. Azure Functions 진단 에이전트, FastAPI 기반 멀티테넌트 API, React 기반 Teams 앱을 연결하고 KQL·Resource Graph·Log Analytics를 활용한 11개 진단 규칙을 구현했습니다.','진단 실행과 결과 수집을 비동기 경계로 분리하고, 읽기 전용 최소 권한·테넌트 데이터 경계·재시도 가능한 처리 흐름을 함께 설계해 클라우드 진단 서비스를 제품 흐름으로 완성했습니다.',3,1,NULL),(4,'PROJECT','음성 스트리밍 및 RAG 면접 관리 (기여도 100%)','2025-12-01','2026-03-31','실시간 AI 모의면접 및 역량 평가 서비스의 전체 시스템 아키텍처와 분산 메시징 처리 부분을 담당했습니다. gRPC 기반 실시간 음성 스트리밍 제어, Redis/Kafka 비동기 메시지 큐를 통한 음성 데이터 및 AI 상태 변경 큐잉, 이력서 RAG 질문 생성 기능 등을 구현하고 Kubernetes 환경에 배포했습니다. (개인 프로젝트)','비동기 메시징 및 대용량 음성 스트리밍 환경에서 발생할 수 있는 데이터 유실과 지연 병목을 제어하며 분산 인프라 설계 능력을 키웠습니다.',4,0,NULL),(6,'EDUCATION','스포츠의학과 학사 졸업','2022-02-25','2022-02-25','IT 비전공자로서 개발 역량을 별도로 쌓았습니다.','스포츠의학을 전공한 뒤 개발 교육과 프로젝트, 실무 경험을 통해 소프트웨어 개발 역량을 쌓았습니다.',17,1,NULL),(7,'EDUCATION','AI 엔지니어링 과정 (3기)','2025-09-01','2026-03-15','ML/DL 기초학습, Agentic AI 구축 (LangChain, LangGraph), RAG 구축, AI Azure 기반의 클라우드 엔지니어 학습 (600시간)','Agentic AI와 RAG 아키텍처를 깊이 있게 다루고, 클라우드 환경에서 AI 인프라를 구축하고 운영하는 방법을 익혔습니다.',7,1,NULL),(8,'EDUCATION','풀스택 프로젝트 실무과정','2023-05-01','2023-10-31','TypeScript 기반 풀스택 교육으로 주로 JavaScript/TypeScript 언어에 대한 깊은 이해와 프레임워크 사용법 등을 학습 (265시간)','TypeScript와 React/Express 환경에서 웹 애플리케이션의 풀스택 개발 생태계와 협업 워크플로우를 체화했습니다.',9,1,NULL),(9,'EDUCATION','파이썬 기반 풀스택 부트캠프','2022-06-01','2022-12-31','풀스택 교육으로 Git, HTML, CSS, Django Template Engine을 활용한 MVC 기반 웹사이트 구현 기초를 학습 (980시간)','소프트웨어 개발의 첫 단추인 MVC 아키텍처와 웹 표준, 형상 관리 도구의 기초를 탄탄히 다졌습니다.',12,1,NULL),(10,'CERTIFICATE','정보처리기사','2022-06-17','2022-06-17','IT 전반의 핵심 이론 및 기술 자격 검증','개발 생명주기 전반에 걸친 기초 체력을 공인 자격을 통해 입증했습니다.',13,1,NULL),(11,'CERTIFICATE','SQL 개발자(SQLD)','2024-09-20','2024-09-20','데이터베이스 모델링 및 SQL 작성 능력 검증','데이터베이스를 단순히 저장소로 쓰는 것을 넘어 성능과 무결성을 고려하여 쿼리하고 모델링할 수 있음을 검증했습니다.',14,1,NULL),(12,'CERTIFICATE','빅데이터분석기사','2022-07-15','2022-07-15','데이터 수집, 전처리, 분석 모형 설계 및 평가 역량 검증','데이터를 수집하고 전처리하여 통계적 기법과 ML 모형으로 분석해 유의미한 가치를 추출할 수 있는 이론적 토대를 닦았습니다.',15,1,NULL),(13,'CERTIFICATE','컴퓨터활용능력 1급','2018-11-16','2018-11-16','스프레드시트 및 데이터베이스 활용 능력 자격 검증','정량적 데이터 정제 및 비즈니스 데이터 처리에 필요한 기본 오피스 역량을 인증받았습니다.',16,0,NULL),(17,'PROJECT','학습 플랫폼 핵심 애플리케이션 API 개발','2023-12-26','2025-09-15','커리큘럼 기반 학습 플랫폼의 핵심 API에서 대화형 AI 학습, 교사용 학습 현황 관리, 통계 조회 구조 개선과 데이터 이관을 담당했습니다.','main 브랜치 9,521개 커밋 중 4,110개를 담당한 최다 기여자로서, 신규 도메인의 adapter·application·domain·infrastructure 전 계층을 구현하고 운영 중 기능을 지속 개선했습니다.',6,0,NULL),(18,'PROJECT','Spring Boot 기반 무료체험 백오피스 구축','2025-05-19','2025-09-10','자발적 사내 TF에서 무료체험 신청·운영 백오피스의 Spring Boot API와 인증·알림·컨테이너 운영 구성을 담당했습니다.','커밋된 144개 Java 소스 파일 규모의 백엔드를 설계하고, 기획부터 운영 수정까지 백엔드 범위를 끝까지 담당했습니다.',8,0,NULL),(19,'PROJECT','학습 플랫폼 BFF 초기 구축 및 운영','2025-01-23','2025-09-09','NestJS 기반 BFF를 초기 구축하고 인증·인가, 서버 간 통신, 공통 오류 처리, 화면별 API와 배포 기반을 개발했습니다.','main 브랜치 564개 커밋 중 316개를 담당하며 공통 기반과 주요 기능을 개발하고 v1.4.0까지 릴리스를 이어갔습니다.',10,0,NULL),(20,'PROJECT','공용 문항 조회 서비스와 사내 공통 개발 기반 구축','2025-08-28','2025-09-19','여러 서비스가 함께 사용하는 문항 조회 API와 공통 백엔드 패키지, 신규 서비스 및 모듈 생성 도구를 구축했습니다.','서비스 저장소와 공통 개발 기반을 함께 구축하고, 분리한 공통 패키지와 생성 템플릿을 신규 조회 서비스에 실제 적용했습니다.',11,0,NULL),(21,'PROJECT','개인 풀스택 포트폴리오 플랫폼 구축 (Self-Intro)','2026-07-13',NULL,'Spring Boot 백엔드와 Next.js 프론트엔드로 구성된 개인 포트폴리오 웹 애플리케이션입니다. 경력·프로젝트·스터디 콘텐츠를 11개 도메인 모듈로 나누어 관리하고, 브라우저 기반 인쇄/PDF 내보내기, 도메인별로 격리된 LLM 연동, Ko-fi 후원 결제, Kubernetes·ArgoCD GitOps 배포까지 전체 스택을 단독으로 설계·구현·운영했습니다.','11개 도메인 모듈로 나뉜 백엔드와 도메인별 어드민 화면을 갖춘 프론트엔드를 함께 설계하며, 콘텐츠 관리·AI 연동·결제·배포까지 서비스 전 영역을 혼자 구축하고 운영하는 경험을 쌓았습니다.',2,1,NULL);
INSERT INTO `experience_detail` (`id`, `experience_id`, `content`, `display_order`, `situation`, `task`, `action_detail`, `outcome`, `narrative`, `visible`) VALUES (1,17,'다양한 학습 유형을 지원하는 대화형 AI 기능 구축',0,'서로 다른 학습 유형에서 대화형 AI 기능을 제공해야 했지만, 유형마다 데이터 구조가 달라 기능별로 별도 구현하면 중복과 변경 범위가 커질 수 있었습니다.','학습 유형별 차이는 분리하면서 세션 생성, 메시지 저장, 외부 AI 응답 처리와 조회 흐름은 공통으로 사용할 수 있게 설계했습니다.','- 학습 유형별 입력 변환 책임과 공통 대화 세션 모델 분리\n- 사용자·AI·시스템 메시지와 텍스트·이미지 콘텐츠 구조 설계\n- 외부 AI 응답을 비동기 메시지로 받아 성공·실패 상태 반영\n- 데이터 변경 구간에 트랜잭션 적용\n- 세션·메시지 조회와 응답 평가 API 구현','여러 학습 유형이 하나의 대화 처리 흐름을 공유하면서도 유형별 변경을 독립적으로 반영할 수 있는 구조를 구축했습니다.','서로 다른 학습 유형에서 대화형 AI 기능을 제공해야 했지만 유형마다 데이터 구조가 달라 기능별로 별도 구현하면 중복과 변경 범위가 커질 수 있었습니다. 학습 유형별 입력 변환 책임과 공통 대화 세션 모델을 분리하고, 사용자·AI·시스템 메시지와 텍스트·이미지 콘텐츠 구조를 설계했습니다. 외부 AI 응답은 비동기 메시지로 받아 성공·실패 상태를 반영하고 데이터 변경 구간에는 트랜잭션을 적용했습니다. 그 결과 여러 학습 유형이 하나의 대화 처리 흐름을 공유하면서도 유형별 변경을 독립적으로 반영할 수 있는 구조를 구축했습니다.',1),(2,19,'프론트엔드 요구에 맞춘 BFF 공통 기반 구축',0,'프론트엔드가 여러 백엔드 API를 화면별로 조합하면서 인증 정보 전달과 오류 처리 로직이 반복되고 있었습니다.','인증·인가, 서버 간 통신, 공통 오류 처리와 화면별 응답 조합을 담당할 BFF의 초기 기반을 구축했습니다.','- NestJS 서버와 환경 설정, Docker 개발 환경 구성\n- 인증 정보 추출과 역할 기반 접근 제어 구현\n- 서버 간 HTTP 통신과 timeout·gateway·network 오류 변환 구성\n- API 문서, 공통 예외 처리, 로깅과 모니터링 연동\n- 교사용 관리와 대화형 AI 기능 등 화면별 중계 API 개발','프론트엔드가 인증 전달과 서버별 오류 변환을 반복하지 않고 화면에 필요한 데이터를 일관된 BFF API로 소비할 수 있게 했습니다.','프론트엔드가 여러 백엔드 API를 화면별로 조합하면서 인증 정보 전달과 오류 처리 로직이 반복되고 있었습니다. 이를 해결하기 위해 NestJS 서버와 환경 설정, Docker 개발 환경을 구성하고 인증 정보 추출과 역할 기반 접근 제어를 구현했습니다. 서버 간 HTTP 통신에는 timeout·gateway·network 오류 변환을 적용하고 API 문서, 공통 예외 처리, 로깅과 모니터링을 연결했습니다. 이후 화면별 중계 API를 개발해 프론트엔드가 인증 전달과 서버별 오류 처리를 반복하지 않고 필요한 데이터를 일관된 BFF API로 소비할 수 있게 했습니다.',1),(3,18,'무료체험 신청·운영 API와 알림 흐름 구축',0,'무료체험 신청, 유입경로, 프로모션과 운영 알림이 여러 수작업으로 나뉘어 있어 TF가 함께 사용할 백오피스 API가 필요했습니다.','신청부터 상태 관리까지의 도메인을 설계하고, 운영 담당자가 필요한 알림을 외부 채널과 연동했습니다.','- 신청·상태·유입경로·프로모션·약관·직원·대여 업무 API 구현\n- 광고·제휴·직원 QR 등 유입경로 분류와 조회 기능 개발\n- 카카오 알림톡 요청 서명 및 발송 연동\n- Microsoft Teams 운영 알림 연동\n- 기획·프론트엔드·운영 담당자의 변경 요청을 반영하며 운영 수정','무료체험 신청과 운영 상태를 백오피스 API에서 관리하고, 신청 이벤트를 알림톡과 Teams로 전달하는 업무 흐름을 구축했습니다.','무료체험 신청, 유입경로, 프로모션과 운영 알림이 수작업으로 나뉘어 있어 TF가 함께 사용할 백오피스 API가 필요했습니다. 신청·상태·유입경로·프로모션·약관·직원·대여 업무를 API로 구현하고 광고·제휴·직원 QR 등 유입경로 분류와 조회 기능을 개발했습니다. 카카오 알림톡과 Microsoft Teams 운영 알림을 연동하고 기획·프론트엔드·운영 담당자의 변경 요청을 반영했습니다. 그 결과 신청과 상태 관리, 운영 알림을 하나의 백엔드 업무 흐름으로 연결했습니다.',1),(4,19,'BFF dev·stg·prod 배포 파이프라인과 릴리스 운영',1,'새 BFF를 로컬 개발뿐 아니라 dev·stg·prod 환경에 반복 배포하고, 환경별 설정과 관측성 구성을 함께 유지해야 했습니다.','컨테이너 빌드부터 ECS 배포까지 환경별 파일과 워크플로우를 구성하고 기능 변경을 버전 릴리스로 관리했습니다.','- Dockerfile과 docker-compose 개발 환경 작성\n- dev·stg·prod ECS task definition 구성\n- develop 자동 빌드 및 환경별 수동 배포 GitHub Actions workflow 작성·유지\n- Datadog tracer와 ECS 로그 설정 연동\n- v1.0.0부터 v1.4.0까지 버전 갱신 및 릴리스 유지','동일한 BFF 애플리케이션을 세 환경에 배포할 수 있는 반복 가능한 경로를 만들고, 기능 변경을 v1.4.0까지 릴리스 단위로 운영했습니다.','새 BFF를 로컬 개발뿐 아니라 dev·stg·prod 환경에 반복 배포하려면 환경별 설정과 관측성 구성을 함께 유지해야 했습니다. Dockerfile과 docker-compose를 작성하고 세 환경의 ECS task definition, develop 브랜치 자동 빌드, 환경별 수동 배포 GitHub Actions workflow를 구성했습니다. 또한 Datadog tracer와 ECS 로그 설정을 연결하고 기능 변경에 맞춰 v1.0.0부터 v1.4.0까지 버전을 갱신했습니다. 그 결과 동일한 BFF 애플리케이션을 세 환경에 전달하는 반복 가능한 배포 경로와 릴리스 이력을 유지했습니다.',1),(5,20,'공통 백엔드 패키지와 서비스 생성 도구 구축',1,'신규 백엔드 서비스를 만들 때 예외 처리, 서버 초기화, 데이터베이스·메시징 설정과 배포 파일을 반복 작성하고 있었습니다.','반복 코드를 역할별 공통 패키지로 분리하고, 새 서비스와 기능 모듈의 기본 구조를 생성하는 도구를 구현했습니다.','- 예외 처리·HTTP 통신·공통 인터페이스 패키지 분리\n- 서버 초기화·입력 검증·API 문서 설정 패키지 분리\n- 데이터베이스·캐시·메시징·파일 저장소 연동 패키지 분리\n- 신규 서비스와 기능 모듈 생성 명령 구현\n- Docker·ECS·GitHub Actions가 포함된 배포 템플릿 작성','공통 코드를 패키지와 생성 템플릿으로 재사용할 수 있게 하고, 새로 구축한 공용 조회 서비스에 실제 적용했습니다.','신규 백엔드 서비스를 만들 때 예외 처리, 서버 초기화, 데이터베이스·메시징 설정과 배포 파일을 반복 작성하고 있었습니다. 예외 처리와 HTTP 통신, 서버 초기화와 API 문서, 데이터베이스·캐시·메시징·파일 저장소 연동을 역할별 공통 패키지로 분리했습니다. 또한 신규 서비스와 기능 모듈의 기본 구조를 만들고 Docker·ECS·GitHub Actions 파일까지 생성하는 도구를 구현했습니다. 그 결과 공통 코드를 패키지와 생성 템플릿으로 재사용할 수 있게 하고 새로 구축한 공용 조회 서비스에 실제 적용했습니다.',1),(6,2,'네이버 로그인 보안 우회 및 Playwright 기반 세션 관리 자동화',2,'네이버 카페 문의 수집 및 답변 등록 시, 캡차 및 2단계 인증 등 강력한 로그인 보안 정책으로 단순 API 직접 호출이 불가능하고 세션 만료 시마다 수동 개입이 수반됨.',NULL,'- Playwright Headless 브라우저 워커 구축\n- 스마트폰 네이버 앱 8자리 OTP 입력 로그인 자동화\n- NID_AUT, NID_SES 쿠키 AES-256-GCM 암호화 DB 보관\n- 응답 바디 세션 노출 방지를 위한 HTTP Set-Cookie 및 X-Naver-Cookie 헤더 전송 구조 전환','수동 로그인 개입을 원클릭 OTP 번호 입력으로 일원화하고, 세션 유효성 강제 동기화(syncSessionStatus) 및 네이버 카페 내 게시글 답변·대댓글 자동 등록 E2E 파이프라인 안착.','네이버 카페 문의 수집 및 답변 등록 시, 캡차 및 2단계 인증 등 로그인 보안 정책으로 단순 API 호출이 불가능하고 세션 만료 시마다 수동 개입이 수반되는 상황이었습니다. 이에 폐쇄망 동작이 가능한 Playwright 워커 구축과 일회용 번호(OTP) 기반 자동 로그인 및 쿠키 노출 방지 전송 구조 구현을 목표로 설정했습니다. Playwright Headless 브라우저 워커를 구축하여 스마트폰 네이버 앱의 8자리 OTP 입력 로그인 과정을 자동화하고, NID_AUT 및 NID_SES 세션 쿠키를 AES-256-GCM으로 암호화하여 DB에 저장했습니다. 또한 응답 바디의 세션 노출을 방지하고자 HTTP Set-Cookie 및 X-Naver-Cookie 헤더 방식으로 전송 구조를 전환했습니다. 그 결과 수동 로그인 개입을 OTP 번호 입력으로 일원화하고, 세션 유효성 강제 동기화 및 네이버 카페 게시글 답변·대댓글 자동 등록 E2E 파이프라인을 구축했습니다.',1),(7,2,'이메일 헤더 분석 및 본문 정규화를 통한 문의 스레드/상태 자동 연동 엔진',4,'이메일 고객 문의 유입 시 동일 사용자의 회신이나 관련 메일이 개별 건으로 무작위 적재되어 CS 상담원의 중복 답변 및 문의 맥락 파편화가 발생함.',NULL,'- RFC 5322 이메일 헤더(Message-ID, In-Reply-To, References) 파싱으로 부모 문의 역추적\n- 회신 접두사(Re:, Fwd:) 제거 정규화 및 발신자 이메일 HMAC-SHA256 해시값(email_sender_hash) B-Tree 인덱스 기반 Heuristic 매칭\n- RESOLVED 문의에 추가 회신 유입 시 OPEN 상태 자동 복귀 및 InquiryWorkLog 감사 로깅','회신 메일의 중복 티켓 생성 방지, 연관 문의 단일 스레드 통합을 통한 CS 상담 컨텍스트 일원화, 해결된 문의의 자동 재오픈을 통한 문의 누락 방지 구조 확립.','이메일 고객 문의 유입 시 동일 사용자의 회신이나 관련 메일이 개별 건으로 무작위 적재되어 CS 상담원의 중복 답변 및 문의 맥락 파편화가 발생하는 상황이었습니다. 이에 이메일 헤더 추적과 Heuristic 매칭을 결합해 파편화된 이메일을 단일 대화 스레드로 자동 병합하고 고객 회신 시 문의 상태를 자동으로 제어하는 과제를 수행했습니다. RFC 5322 이메일 헤더(Message-ID, In-Reply-To, References) 파싱으로 부모 문의를 역추적해 스레딩 체인을 구축하고, 헤더 유실 시에는 회신 접두사(Re:, Fwd:) 제거 정규화와 발신자 이메일 HMAC-SHA256 해시 B-Tree 인덱스 조회를 결합한 Heuristic 매칭을 적용했습니다. 또한 RESOLVED 상태 문의에 추가 회신 유입 시 OPEN 상태로 자동 변경하고 감사 로그에 이력을 기록하도록 개발했습니다. 이를 통해 회신 메일의 중복 티켓 생성을 방지하고, 연관 문의를 단일 대화 스레드로 통합하여 CS 상담 컨텍스트 일원화 및 해결 문의 재오픈 자동화를 구현했습니다.',0),(8,2,'JPA Converter 기반 개인정보(PII) AES/GCM 암호화 및 무중단 마이그레이션',3,'고객 문의 본문, 이메일, 전화번호 등 민감 개인정보(PII)가 DB에 평문 저장되어 개인정보보호법 준수 및 유출 리스크가 존재함.',NULL,'- JPA AttributeConverter(EncryptedStringConverter) 및 Jackson Mixin 기반 AES-256-GCM 암복호화 적용\n- 발신자 이메일 단방향 HMAC-SHA256 해시(email_sender_hash) 컬럼 설계로 O(log N) B-Tree 인덱스 등치 조회 구현\n- 복호화 실패 시 평문을 반환하는 decryptOrPassThrough 하위 호환 로직 및 독립 CLI 마이그레이션 도구(PiiEncryptionMigrationTool) 가동','DB 유출 시에도 안전한 PII 암호화 보안 규격을 달성하고, 앱 기동 중단 없는 무중단(Zero-Downtime) 암호화 마이그레이션 체계 완수.','고객 문의 데이터 내 개인정보(PII)가 DB에 평문 저장되어 개인정보보호법 준수 및 유출 리스크가 존재하는 상황이었습니다. 이에 영속성 계층 암복호화 자동화, 빠른 등치 조회를 위한 해시 컬럼 구축, 기존 평문 데이터의 무중단 암호화 이관을 목표로 설정했습니다. JPA AttributeConverter 및 Jackson Mixin 기반 AES-256-GCM 영속성 계층 암복호화를 적용하고, 암호문의 무작위 IV 특성으로 인한 등치 검색 불가를 해결하고자 발신자 이메일 단방향 HMAC-SHA256 해시 컬럼을 추가해 B-Tree 인덱스 조회를 구현했습니다. 또한 복호화 실패 시 평문을 반환하는 Decrypt-or-PassThrough 예외 처리와 독립 CLI 마이그레이션 도구를 활용해 이관 작업을 가동했습니다. 그 결과 DB 유출 시에도 안전한 PII 암호화 보안 규격을 달성하고, 앱 기동 중단 없는 무중단(Zero-Downtime) 데이터 암호화 이관을 완료했습니다.',1),(9,2,'n8n 워크플로우 및 Spring Boot REST API 기반 멀티채널 문의 통합 수집 파이프라인',0,'네이버 카페, 이메일, 구글 시트 등 다중 채널 문의 내역을 수동 수집 관리함에 따른 행정 공수 낭비 및 데이터 파편화가 발생함.',NULL,'- n8n 노코드 워크플로우로 5분 주기 네이버 카페 크롤링 및 IMAP 메일 수신 자동화\n- Spring Boot 백엔드에서 4종 다형적 JSONB 메타데이터(EmailMetadata, NaverCafeMetadata 등) 구조 검증 및 parsing 처리\n- InquiryUniqueKeyGenerator 고유 키 생성 엔진 및 JDBC bulkInsert 구현\n- MinIO S3 오브젝트 스토리지 연동 및 첨부 이미지 상대경로 JSONB 매핑 최적화','이종 채널의 문의 데이터를 단일 DB 스키마로 통합 수집하고, 고유키 기반 중복 방지 및 파일 스토리지 연동 인프라 안착.','네이버 카페, 이메일, 구글 시트 등 다중 채널 문의 내역을 수동 수집 관리함에 따라 행정 공수 낭비 및 데이터 파편화가 발생하는 상황이었습니다. 이에 채널별 정형화 수집 자동화, 수집 중복 방지 멱등성 보장, 첨부파일 S3 스토리지 연동을 과제로 추진했습니다. n8n 노코드 워크플로우로 5분 주기 크롤링 및 IMAP 수신을 자동화하고, 백엔드에서 4종 다형적 JSONB 메타데이터 구조 검증과 고유 키 기반 중복 방지 및 JDBC bulkInsert를 연동했습니다. 또한 MinIO S3 오브젝트 스토리지를 연동해 첨부 이미지 저장 및 상대경로 JSONB 매핑을 처리했습니다. 이를 통해 이종 채널의 문의 데이터를 단일 DB 스키마로 통합 수집하고, 고유 키 기반 중복 유입 방지 및 파일 스토리지 연동 수집 파이프라인을 구축했습니다.',1),(10,2,'Nginx auth_request 계층 SSO 연동 및 통합 접근 제어 구축',1,'백오피스, n8n, Grafana, MinIO 콘솔 등 개별 어드민 도구들에 대한 접근 제어 파편화 및 외부 무단 접속 위협이 존재함.',NULL,'- Nginx Reverse Proxy 수준 LAN/VPN IP 필터링 & Basic Auth 적용 및 X-Remote-User 신뢰 헤더 터널링\n- Nginx auth_request /_admin_tool_auth 지시어와 백엔드 /api/v1/auth/admin-tool-check 서브루틴 연동\n- cs_admin_access 쿠키 기반 어드민 툴(/n8n/, /grafana/, /minio/) 통합 접근 통제','백오피스 및 개발/운영 어드민 도구들의 보안 접근 규격을 단일 통로로 일원화하고 무단 외부 접근 차단.','사내 백오피스, n8n, Grafana, MinIO 콘솔 등 개별 어드민 도구들에 대한 접근 제어 파편화 및 외부 무단 접속 위협이 존재하는 상황이었습니다. 이에 경계 네트워크 보안 강화, 외부 무단 접근 차단 및 쿠키 기반 단일 인증(SSO) 위임 처리를 목표로 설정했습니다. Nginx Reverse Proxy 수준에서 LAN/VPN IP 필터링과 Basic Auth를 적용하고 검증된 사용자명을 X-Remote-User 헤더로 연동했습니다. 또한 Nginx auth_request 지시어를 통해 백엔드 인증 검증 엔드포인트를 호출하도록 구성하고 전용 쿠키 기반 권한 검증을 처리했습니다. 그 결과 개별 어드민 도구의 보안 접근 규격을 단일 통로로 일원화하고 무단 외부 접근을 차단했습니다.',1),(11,3,'11개 규칙을 확장 가능한 진단 엔진으로 구현',0,'Azure 리소스마다 로그 연결 상태, 애플리케이션 상태, 불필요한 수집과 보존 비용을 확인하는 방법이 달라 진단 로직이 쉽게 중복될 수 있었습니다.','서로 다른 진단 기준을 같은 실행 계약으로 묶고, 리소스 탐색부터 근거 수집과 처방 생성까지 일관되게 확장할 수 있는 엔진을 구축했습니다.','- 공통 추상화와 등록 구조로 진단 규칙의 실행 계약 통일\n- 로그 비용·관측성·수집 예방·필터링의 네 영역에 11개 규칙 구현\n- Azure Resource Graph와 관리 API로 리소스 및 로그 연결 관계 탐색\n- Log Analytics에 KQL을 실행해 사용량·상태·요청 지표 수집\n- 규칙별 근거와 권장 조치를 동일한 결과 형식으로 변환','11개 진단 규칙을 독립적으로 추가·실행할 수 있는 엔진을 완성하고, 24개 테스트 파일로 주요 규칙과 공통 흐름을 검증했습니다.','Azure 리소스마다 로그 연결 상태, 애플리케이션 상태, 불필요한 수집과 보존 비용을 확인하는 방법이 달라 진단 로직이 중복될 수 있었습니다. 공통 추상화와 등록 구조로 실행 계약을 통일하고 로그 비용·관측성·수집 예방·필터링의 네 영역에 11개 규칙을 구현했습니다. Resource Graph와 관리 API로 대상과 연결 관계를 찾고 Log Analytics의 KQL 결과를 규칙별 근거와 권장 조치로 변환했습니다. 그 결과 규칙을 독립적으로 추가·실행할 수 있는 진단 엔진을 완성하고, 24개 테스트 파일로 주요 규칙과 공통 흐름을 검증했습니다.',1),(12,3,'Durable Functions 기반 병렬 진단 오케스트레이션 구축',1,'여러 구독과 리소스를 탐색한 뒤 각 진단 규칙의 외부 API·KQL 작업을 실행해야 해 단일 요청에서 순차 처리하기에는 작업 시간이 길고 일시적 실패에도 취약했습니다.','장시간 진단을 트리거·오케스트레이터·액티비티로 분리하고 병렬 실행, 재시도와 상태 복구가 가능한 흐름을 구축했습니다.','- Queue와 Timer 트리거로 수동·예약 진단 진입점 구성\n- 리소스 탐색, 연결 조회, 규칙 실행, 결과 전송을 액티비티로 분리\n- 병렬 실행 후 결과를 모으는 fan-out/fan-in 구조 적용\n- 외부 호출 액티비티에 재시도 정책 적용\n- 완료된 진단 결과를 제공자 큐로 전달','작업 상태를 Durable Functions가 보존하고 독립 액티비티를 병렬·재시도하도록 구성해, 장시간 진단을 HTTP 요청 수명과 분리했습니다.','여러 구독과 리소스를 탐색한 뒤 각 진단 규칙의 외부 API와 KQL 작업을 실행해야 해 단일 요청의 순차 처리로는 장시간 작업과 일시적 실패를 다루기 어려웠습니다. Queue와 Timer 트리거를 두고 리소스 탐색, 연결 조회, 규칙 실행, 결과 전송을 액티비티로 분리했습니다. 오케스트레이터에서는 fan-out/fan-in으로 독립 작업을 병렬 실행하고 외부 호출에는 재시도 정책을 적용했습니다. 그 결과 작업 상태를 보존하면서 진단을 HTTP 요청 수명과 분리하고, 완료 결과를 다음 처리 큐로 전달하는 흐름을 구축했습니다.',1),(13,3,'읽기 전용 최소 권한의 고객 환경 진단 에이전트 설계',3,'고객 Azure 환경을 진단하려면 여러 리소스와 로그를 조회해야 하지만, 진단 기능에 변경·삭제 권한을 부여하면 보안 범위가 불필요하게 커질 수 있었습니다.','진단에 필요한 조회 범위를 코드와 배포 정의에서 식별하고, 고객 환경을 변경하지 않는 별도 에이전트와 권한 모델로 배포했습니다.','- 관리 리소스 조회 12개와 로그 데이터 조회 1개로 사용자 지정 역할 구성\n- 관리 작업과 데이터 작업 권한을 구분해 명시\n- Azure Functions 진단 에이전트와 관리형 ID 기반 인증 구성\n- Bicep으로 에이전트·저장소·AI 리소스와 역할 할당 자동화\n- 제공자 API의 사용자·테넌트·에이전트 접근 검증 적용','진단 에이전트의 Azure 접근을 필요한 읽기 작업으로 제한하고, 애플리케이션과 인프라의 권한 경계를 배포 코드로 재현할 수 있게 했습니다.','고객 Azure 환경을 진단하려면 여러 리소스와 로그를 조회해야 하지만 진단 기능에 변경·삭제 권한까지 부여하면 보안 범위가 커질 수 있었습니다. 실제 조회 경로를 기준으로 관리 리소스 조회 12개와 로그 데이터 조회 1개를 사용자 지정 역할로 구성하고, 관리 작업과 데이터 작업을 구분했습니다. Azure Functions 에이전트는 관리형 ID로 인증하고 Bicep으로 리소스와 역할 할당을 재현했으며 제공자 API에는 사용자·테넌트·에이전트 접근 검증을 적용했습니다. 그 결과 고객 환경을 변경하지 않는 읽기 전용 진단 경계를 명시적으로 구축했습니다.',1),(14,3,'Teams 안에서 이어지는 온보딩·진단·알림 경험 구축',4,'사용자가 Azure Portal과 별도 관리 화면을 오가며 에이전트를 설치하고 진단 진행 상태와 결과를 확인하면 서비스 이용 흐름이 단절될 수 있었습니다.','Teams 앱 안에서 초기 설정, 권한 위임, 에이전트 관리, 진단 실행과 결과 확인, 알림 설정까지 이어지는 사용자 흐름을 구현했습니다.','- Teams 개인·팀 탭과 알림 전용 봇 매니페스트 구성\n- SSO 기반 사용자 확인과 테넌트 설정·배포 위임 화면 구현\n- 에이전트·구독·예약 진단 및 알림 설정 화면 구현\n- 진단 진행률·위험 요약·이력·상세 결과 대시보드 구현\n- 진단 완료와 운영 이벤트를 Teams 알림 및 딥링크로 연결','설치와 관리부터 진단 결과 확인까지의 주요 기능을 Teams 안에 연결하고, 비동기 작업 완료를 알림에서 상세 화면으로 이어지게 했습니다.','사용자가 Azure Portal과 별도 관리 화면을 오가며 에이전트를 설치하고 진단 결과를 확인하면 서비스 이용 흐름이 단절될 수 있었습니다. Teams 개인·팀 탭과 알림 전용 봇을 구성하고 SSO 기반 사용자 확인, 테넌트 설정과 배포 위임, 에이전트·구독·예약 진단 및 알림 설정 화면을 구현했습니다. 진단 진행률, 위험 요약, 이력과 상세 결과를 대시보드로 제공하고 완료 알림의 딥링크를 상세 화면에 연결했습니다. 그 결과 설치와 관리부터 비동기 진단 결과 확인까지의 주요 흐름을 Teams 안에서 이어지게 했습니다.',1),(15,4,'음성 스트리밍 파이프라인 및 RAG 최적화 설계',0,'실시간 AI 모의면접 중 음성 유실과 지연 병목 현상 해결 및 RAG 엔진의 이력서 분석 정확도 개선이 요구되었습니다.',NULL,'- gRPC 기반의 음성 데이터 스트리밍 채널을 확보하고, Kafka/Redis 메시지 큐를 결합해 마이크로서비스 간 비동기 상태를 통제했습니다.\n- PDF 이력서 정보를 파싱한 뒤 문서 청킹 및 임베딩 단계를 최적화하고, Rerank 모델을 결합해 RAG 질문 생성의 정밀성을 높였습니다.','음성 끊김 현상을 최소화하고 이력서 매칭 성능을 확보하여 실시간 평가 가용성을 보장했습니다.',NULL,1),(17,6,'스포츠의학과 학사 학위 취득 (IT 비전공)',0,'',NULL,'','차의과학대학교 스포츠의학과를 졸업했으며, IT 비전공자로서 개발 역량을 별도로 쌓았습니다.',NULL,1),(18,7,'AI 및 클라우드 엔지니어링 600시간 이수',0,NULL,NULL,NULL,'ML/DL 기초학습, Agentic AI 구축(LangChain, LangGraph), RAG 구축, AI Azure 기반의 클라우드 엔지니어링 파이프라인을 학습했습니다.',NULL,1),(19,8,'TypeScript 기반 풀스택 교육 이수',0,NULL,NULL,NULL,'TypeScript와 React/Express 환경에서 웹 애플리케이션의 풀스택 개발 생태계와 협업 워크플로우를 학습했습니다.',NULL,1),(20,9,'파이썬 기반 풀스택 부트캠프 이수',0,NULL,NULL,NULL,'소프트웨어 개발의 첫 단추인 MVC 아키텍처와 웹 표준, 협업을 위한 형상 관리 도구의 기초를 학습했습니다.',NULL,1),(21,10,'IT 전반의 핵심 이론 및 기술 자격 검증',0,NULL,NULL,NULL,'소프트웨어 공학, 데이터베이스, 네트워크 등 IT 핵심 이론을 검증받아 정보처리기사를 취득했습니다.',NULL,1),(22,11,'RDB 모델링 및 쿼리 최적화 역량 검증',0,NULL,NULL,NULL,'데이터베이스 모델링 및 SQL 작성 능력을 검증받아 SQLD를 취득했습니다.',NULL,1),(23,12,'데이터 전처리 및 분석 모형 설계 역량 검증',0,NULL,NULL,NULL,'데이터 수집, 전처리, 분석 모형 설계 및 평가 역량을 검증받아 빅데이터분석기사를 취득했습니다.',NULL,1),(24,13,'사무 행정 및 데이터베이스 기초 역량 검증',0,'',NULL,'','스프레드시트 및 데이터베이스 활용 능력을 검증받아 컴퓨터활용능력 1급을 취득했습니다.',NULL,1),(25,2,'Logback JSON 로깅 & Grafana Alloy / Loki 관측성 모니터링 구축',5,'분산 컨테이너 환경에서 런타임 예외 발생 시 개별 로그 파일 직접 조회로 인한 원인 추적 비효율 및 모니터링 체계 미비.',NULL,'- logback-spring.xml 구성으로 Machine-Readable JSON Line 로그 파일 분리(app.log, error.log, access.log)\n- Docker Volume 기반 Grafana Alloy 로그 수집기 및 Loki 중앙 인덱싱 연동\n- Grafana 대시보드 구축으로 실시간 5xx 예외 에러율 및 서버 메트릭 가시화','분산 컨테이너 로그의 중앙집중화, 실시간 5xx 예외 감지 대시보드 정착 및 시스템 장애 원인 파악 리드타임 개선.','분산 컨테이너 환경에서 런타임 예외 발생 시 개별 로그 파일 직접 조회로 인한 원인 추적 비효율 및 모니터링 체계가 미비한 상황이었습니다. 이에 Logback 중앙 JSON 로깅, Grafana Alloy/Loki 로그 수집 파이프라인 및 실시간 가시화 대시보드 구축을 과제로 수행했습니다. logback-spring.xml 설정으로 Machine-Readable JSON Line 로그 파일(app.log, error.log, access.log)을 분리 저장하고, Docker Volume 기반 Grafana Alloy 수집기로 로그를 실시간 파싱해 Loki로 중앙 인덱싱 전송했습니다. 이를 Grafana 대시보드와 연동하여 5xx 예외 발생률 및 시스템 메트릭을 구성했습니다. 이를 통해 분산 컨테이너 로그를 중앙집중화하고 실시간 5xx 예외 감지 및 시스템 장애 원인 파악 디버깅 환경을 구축했습니다.',0),(26,1,'직군 간 요구사항을 연결한 자발적 백오피스 TF 협업',0,'무료체험 신청과 운영 과정의 반복 수작업을 개선하기 위해 기획자·디자이너·프론트엔드 개발자·운영 담당자가 참여하는 자발적 TF가 구성되었습니다.','각 직군의 업무 흐름을 API와 운영 가능한 백엔드 기능으로 구체화하고, 백엔드 및 인프라 범위의 구현 책임을 맡았습니다.','- 기획·운영 담당자와 신청 상태, 유입경로, 프로모션 및 알림 흐름 협의\n- 프론트엔드 개발자와 세션 인증, CORS, API 응답 규격 조율\n- 개발 이후 운영 단계의 수정 요청과 서버 핫픽스 대응','직군별 요구사항을 무료체험 신청·관리 API와 알림 흐름으로 연결하고, TF가 실제로 사용할 수 있는 백엔드 운영 기반을 제공했습니다.','무료체험 운영의 반복 수작업을 개선하기 위한 자발적 TF에서 기획자·디자이너·프론트엔드 개발자·운영 담당자와 협업했습니다. 저는 각 직군이 설명하는 신청, 유입경로, 프로모션, 알림 요구사항을 백엔드 도메인과 API 규격으로 구체화하고 세션 인증과 CORS 이슈를 프론트엔드와 함께 조율했습니다. 개발 이후에도 운영 단계의 수정 요청과 서버 핫픽스를 이어가며, 협의된 업무 흐름이 실제로 사용 가능한 백엔드 기능으로 정착하도록 책임졌습니다.',1),(27,1,'반복 릴리스와 서비스별 개발 규칙 정리',1,'핵심 애플리케이션과 신규 BFF, 공용 서비스가 병행 개발되면서 버전 관리와 서비스별 공통 설정을 지속적으로 정리할 필요가 있었습니다.','기능 변경을 릴리스 단위로 관리하고, 새 서비스가 같은 예외 처리·로깅·인프라 규칙을 재사용할 수 있도록 개발 기반을 정리했습니다.','- 핵심 애플리케이션의 버전 갱신과 반복 릴리스 수행\n- BFF 저장소를 최초 커밋부터 구성하고 v1.4.0까지 릴리스 유지\n- 공통 예외 처리·서버 부트스트랩·인프라 모듈을 사내 패키지와 CLI 템플릿으로 정리','장기간 운영되는 기존 서비스와 새로 만드는 서비스 모두에서 변경 이력과 공통 개발 규칙을 이어갈 수 있는 기반을 남겼습니다.','핵심 애플리케이션과 신규 BFF, 공용 서비스가 병행 개발되는 환경에서 기능 변경을 릴리스 단위로 관리했습니다. BFF는 저장소의 최초 커밋부터 기반을 구성해 v1.4.0까지 유지했고, 후반에는 여러 서비스에 반복되던 예외 처리·서버 부트스트랩·인프라 설정을 사내 패키지와 CLI 템플릿으로 정리했습니다. 이를 통해 개별 기능 개발뿐 아니라 팀이 다음 서비스를 만들고 운영할 때 이어서 사용할 수 있는 개발 규칙과 기반을 남겼습니다.',1),(28,17,'교사용 실시간 학습 현황 및 개입 기능 구축',1,'교사가 학생의 접속 상태와 학습 진행 중 확인이 필요한 상황을 파악하고, 필요한 경우 학생에게 조치를 요청할 수 있는 기능이 필요했습니다.','접속 상태, 확인이 필요한 학습 항목, 교사와 학생 간 요청·응답을 각각 독립적으로 관리하는 API를 구축했습니다.','- 온라인·오프라인·백그라운드 상태 기록 및 동기화 API 구현\n- 여러 학습 유형에서 발생하는 확인 항목을 공통 형식으로 조회·처리\n- 교사 요청 생성·조회·응답 상태 변경 API 구현\n- 프론트엔드용 중계 서버에 화면 단위 응답 조합 로직 구성','교사용 화면에서 학생 상태, 확인할 학습 항목, 요청 처리 결과를 일관된 API로 조회하고 변경할 수 있게 했습니다.','교사가 학생의 접속 상태와 학습 진행 중 확인이 필요한 상황을 파악하고 필요한 경우 학생에게 조치를 요청할 수 있는 기능이 필요했습니다. 온라인·오프라인·백그라운드 상태 기록과 동기화 API를 구현하고, 여러 학습 유형에서 발생하는 확인 항목을 공통 형식으로 조회·처리하도록 구성했습니다. 또한 교사 요청의 생성·조회·응답 상태 변경 API와 화면 단위 응답 조합 로직을 개발했습니다. 그 결과 교사용 화면에서 학생 상태, 확인할 학습 항목, 요청 처리 결과를 일관된 방식으로 관리할 수 있게 했습니다.',1),(29,17,'학습 통계 조회 구조 분리와 데이터 이관',2,'하나의 구조에서 여러 기준의 학습 통계를 함께 관리하고 있어 조회 목적별 책임을 분리하고 기존 집계 데이터를 새 구조로 옮길 필요가 있었습니다.','학급·학생·전체·기관 관점의 통계 조회 구조를 분리하고, 기존 데이터의 주요 집계값을 새 저장 구조로 안전하게 이관했습니다.','- 조회 관점별 통계 모델과 읽기·쓰기 저장소 책임 분리\n- 커리큘럼·문항·사용자 범위를 기준으로 기존 데이터 병합\n- 제출·정답·오답·스킵·평가·소요시간 등 14개 지표 이관\n- 트랜잭션 안에서 신규 구조 저장과 기존 데이터 정리 수행','통계 조회 책임을 사용 목적별로 분리하고 기존 집계값을 새 구조로 옮길 수 있는 이관 절차를 마련했습니다.','하나의 구조에서 여러 기준의 학습 통계를 함께 관리하고 있어 조회 목적별 책임을 분리하고 기존 집계 데이터를 새 구조로 옮길 필요가 있었습니다. 학급·학생·전체·기관 관점의 통계 모델과 읽기·쓰기 저장소 책임을 나누고, 커리큘럼·문항·사용자 범위를 기준으로 기존 데이터를 병합했습니다. 제출·정답·오답·스킵·평가·소요시간 등 14개 지표를 트랜잭션 안에서 새 구조로 저장하고 기존 데이터를 정리했습니다. 그 결과 통계 조회 책임을 사용 목적별로 분리하고 기존 집계값을 이관할 수 있는 절차를 마련했습니다.',1),(30,18,'Redis 세션 인증과 백오피스 운영 환경 구성',1,'분리 배포된 프론트엔드와 백오피스 API 사이에서 세션 쿠키를 전달하고, 애플리케이션과 저장소·프록시·로그 화면을 함께 운영해야 했습니다.','크로스도메인 세션 인증을 구성하고 백오피스 실행에 필요한 컨테이너와 프록시, 모니터링 환경을 묶었습니다.','- Spring Security 인증과 Spring Session Data Redis 연동\n- DefaultCookieSerializer SameSite=None 및 secure cookie 설정과 CORS credential 허용\n- Docker Compose로 app·Nginx·MySQL·Redis·Grafana 구성\n- Nginx reverse proxy와 Swagger Basic Auth, Grafana sub-path 연결\n- 운영 서버에서 인증 및 Grafana 로그인 이슈 수정','분리된 프론트엔드가 Redis 기반 서버 세션을 사용할 수 있게 하고, 백오피스 애플리케이션과 필수 운영 컴포넌트를 함께 실행·점검할 수 있는 환경을 구성했습니다.','분리 배포된 프론트엔드와 백오피스 API 사이에서 세션 쿠키를 전달하고 여러 운영 컴포넌트를 함께 실행해야 했습니다. Spring Security와 Spring Session Data Redis를 연동하고 DefaultCookieSerializer의 SameSite=None, secure cookie 설정과 credential을 허용하는 CORS 구성을 적용했습니다. Docker Compose에는 app·Nginx·MySQL·Redis·Grafana를 묶고, Nginx reverse proxy와 Swagger Basic Auth, Grafana sub-path를 구성했습니다. 운영 중에는 인증과 Grafana 로그인 이슈를 수정해 분리된 프론트엔드가 서버 세션을 사용하고 운영자가 애플리케이션 상태를 점검할 수 있는 환경을 마련했습니다.',1),(31,20,'공용 문항 조회 서비스 구축',0,'여러 서비스가 같은 문항 데이터를 각각 조회하는 대신, 조회 책임을 분리한 공용 API가 필요했습니다.','단건·다건 문항 조회 API와 데이터 접근 계층을 구현하고 여러 배포 환경에서 실행할 수 있는 독립 서비스를 구축했습니다.','- 계층형 백엔드 구조로 조회 서비스 구성\n- 단건 조회와 ID 목록 기반 다건 조회 API 구현\n- MongoDB 저장소와 로컬 데이터 초기화·인덱스 구성\n- 대규모 문항 시드 데이터로 로컬 검증 환경 구성\n- Docker·ECS·GitHub Actions 배포 환경 작성','문항 조회 책임을 독립 서비스로 분리하고 여러 호출자가 동일한 API를 통해 문항 데이터를 조회할 수 있게 했습니다.','여러 서비스가 같은 문항 데이터를 각각 조회하는 대신 조회 책임을 분리한 공용 API가 필요했습니다. 계층형 백엔드 구조로 단건 조회와 ID 목록 기반 다건 조회 API를 구현하고 MongoDB 저장소, 로컬 데이터 초기화와 인덱스를 구성했습니다. 대규모 문항 시드 데이터로 로컬 검증 환경을 만들고 Docker·ECS·GitHub Actions 배포 환경을 작성했습니다. 그 결과 문항 조회 책임을 독립 서비스로 분리하고 여러 호출자가 동일한 API를 통해 데이터를 조회할 수 있게 했습니다.',1),(32,3,'비동기 수집과 멀티테넌트 리포트 저장 구조 구현',2,'고객 환경의 진단 결과가 큐를 통해 비동기로 도착하고 여러 테넌트의 리포트·세부 진단·통계를 함께 갱신해야 해 실패 재처리와 동시 수정 충돌을 고려해야 했습니다.','큐 메시지를 안전하게 수집하고 테넌트별 데이터 경계와 동시성 제어를 유지하는 제공자 백엔드를 구축했습니다.','- FastAPI 시작 시 Azure 인증과 데이터 저장소 연결 사전 준비\n- 진단 결과와 완료 요청을 분리한 Azure Queue 비동기 워커 구현\n- 성공한 메시지만 삭제하고 실패 메시지는 재처리하도록 처리 경계 설정\n- Cosmos DB에 테넌트 파티션, 커서 페이지네이션과 ETag 낙관적 동시성 적용\n- 동시 저장 작업을 제한해 데이터 저장소 부하 제어','메시지 성공 여부와 삭제 시점을 일치시키고, 테넌트 경계·동시 수정 검증·페이지네이션을 갖춘 리포트 수집 및 조회 흐름을 구축했습니다.','고객 환경의 진단 결과가 큐를 통해 비동기로 도착하고 여러 테넌트의 리포트와 세부 진단을 함께 갱신해야 해 실패 재처리와 동시 수정 충돌을 고려해야 했습니다. FastAPI 시작 시 Azure 인증과 데이터 저장소 연결을 준비하고, 진단 결과와 완료 요청을 분리한 Queue 워커를 구현했습니다. 성공한 메시지만 삭제해 실패 시 재처리되도록 했으며 Cosmos DB에는 테넌트 파티션, 커서 페이지네이션과 ETag 낙관적 동시성을 적용했습니다. 또한 동시 저장 작업 수를 제한해 부하를 제어했습니다. 그 결과 메시지 처리 경계와 테넌트별 리포트 수명주기를 일관되게 관리할 수 있게 했습니다.',1),(33,21,'도메인별로 분리된 백엔드와 공개/관리자 API 경계 설계',0,'아키텍처, 역량, 후원, 경력·프로젝트, 인쇄 템플릿, 프로필, 스킬, 스토리지, 방문자, 스터디 등 성격이 다른 11개 콘텐츠 도메인을 하나의 포트폴리오 서버로 운영해야 했고, 공개 조회와 관리자 수정 권한을 도메인마다 흩어지지 않게 통일해야 했습니다.',NULL,'- ai/architecture/competency/donation/experience/printtemplate/profile/skill/storage/visitor와 최상위 study까지 11개 도메인을 패키지 단위 모듈로 분리\n- Spring Security 세션 인증으로 /api/admin/**를 ROLE_ADMIN 전용으로 제한하고 공개 GET 엔드포인트는 화이트리스트로 허용\n- CsrfCookieFilter로 CSRF 쿠키 기반 검증을 공개 폼 제출 구간에 적용\n- Flyway로 스키마 변경 이력을 순차 마이그레이션(V1~V64)으로 관리\n- study 도메인의 검색·필터링 쿼리를 QueryDSL로 구현','서로 다른 11개 도메인을 독립된 모듈로 유지하면서도 공개/관리자 API 경계를 하나의 보안 설정으로 통일했고, 64개의 순차 마이그레이션으로 스키마 변경 이력을 추적할 수 있게 했습니다.','아키텍처, 역량, 후원, 경력·프로젝트, 인쇄 템플릿, 프로필, 스킬, 스토리지, 방문자, 스터디 등 성격이 다른 11개 콘텐츠 도메인을 하나의 서버로 운영해야 했습니다. 도메인마다 컨트롤러·서비스·도메인 계층을 독립된 패키지로 분리하고, Spring Security 세션 인증으로 /api/admin/**를 ROLE_ADMIN 전용으로 제한하면서 공개 GET 엔드포인트는 화이트리스트로 열어 두었습니다. CSRF 쿠키 필터를 공개 제출 구간에 적용하고 Flyway로 스키마 변경을 V1부터 V64까지 순차 관리했으며, study 도메인의 검색은 QueryDSL로 구현했습니다. 그 결과 11개 도메인을 독립적으로 유지하면서도 공개/관리자 경계와 스키마 변경 이력을 하나의 기준으로 관리할 수 있었습니다.',1),(34,21,'클라이언트에서 완결되는 이력서 인쇄/PDF 내보내기 시스템 구축',1,'포트폴리오 콘텐츠를 채용 담당자에게 인쇄물이나 PDF로 전달할 방법이 필요했지만, 페이지가 잘리는 위치와 포함할 섹션 구성이 사람마다 달라 고정된 서버 렌더링만으로는 대응하기 어려웠습니다.',NULL,'- PrintCanvas/PdfPageLayer로 페이지 단위 인쇄 레이아웃 렌더링 구현\n- pdfLayoutEngine에서 섹션 높이를 계산해 페이지 분할 지점 산출\n- PrintSkillSelectorModal로 인쇄에 포함할 스킬·섹션을 선택하는 UI 구현\n- SaveServerTemplateModal로 선택한 구성을 PrintTemplate으로 서버에 저장\n- PrintTemplate에 schemaVersion과 baseContentFingerprint를 두어 원본 콘텐츠 변경 시 템플릿 드리프트 감지','서버 PDF 렌더러 없이 브라우저에서 섹션 선택부터 페이지 미리보기, 템플릿 저장까지 이어지는 인쇄 흐름을 완성했고, 원본 콘텐츠가 바뀌었을 때 저장된 템플릿과의 불일치를 감지할 수 있게 했습니다.','포트폴리오 콘텐츠를 채용 담당자에게 인쇄물이나 PDF로 전달해야 했지만, 페이지가 잘리는 위치와 포함할 섹션이 사람마다 달라 고정된 서버 렌더링으로는 대응하기 어려웠습니다. PrintCanvas와 PdfPageLayer로 페이지 단위 레이아웃을 렌더링하고 pdfLayoutEngine이 섹션 높이를 계산해 분할 지점을 산출하도록 했습니다. PrintSkillSelectorModal로 인쇄에 포함할 스킬과 섹션을 고르게 하고, 자주 쓰는 구성은 SaveServerTemplateModal로 PrintTemplate에 저장했습니다. schemaVersion과 baseContentFingerprint를 함께 저장해 원본 콘텐츠가 바뀌면 드리프트를 감지하게 했습니다. 그 결과 서버 PDF 렌더러 없이 브라우저 안에서 완결되는 인쇄 워크플로우를 구축했습니다.',1),(35,21,'여러 도메인에 걸친 LLM 콘텐츠 생성을 기능 플래그로 격리',3,'역량, 경력, 스터디 세 도메인에서 각각 AI로 초안을 생성하는 기능이 필요했지만, 하나의 AI 연동 장애나 설정 문제가 전체 콘텐츠 관리 기능을 막지 않도록 격리해야 했습니다.',NULL,'- Spring AI ChatClient로 NVIDIA NIM(OpenAI 호환 API, Qwen3.5 계열 모델)을 감싸는 공용 NvidiaNimClient 구현\n- CompetencyAiService/ExperienceAiService/StudyAiService가 각자의 도메인 규칙에 맞춰 공용 클라이언트를 호출\n- COMPETENCY_AI_ENABLED/EXPERIENCE_AI_ENABLED/STUDY_AI_ENABLED 세 개의 독립 플래그로 도메인별 활성화 여부 제어(기본값 비활성화)\n- 동기 생성 응답과 SSE 스트리밍 응답을 함께 지원\n- AiJsonSupport로 AI 응답 JSON 파싱 로직을 공통화','세 도메인이 같은 AI 클라이언트를 공유하면서도 서로 독립적으로 켜고 끌 수 있게 했고, 한 도메인의 AI 기능 문제가 다른 도메인의 수동 콘텐츠 관리를 막지 않도록 분리했습니다.','역량, 경력, 스터디 세 도메인에서 각각 AI로 초안을 생성해야 했지만, 하나의 AI 연동 문제가 전체 콘텐츠 관리를 막지 않도록 격리해야 했습니다. Spring AI ChatClient로 NVIDIA NIM을 감싸는 공용 NvidiaNimClient를 만들고, CompetencyAiService/ExperienceAiService/StudyAiService가 각자의 도메인 규칙에 맞춰 이를 호출하게 했습니다. 세 도메인 각각에 독립된 활성화 플래그를 두어 기본값은 꺼둔 채 필요한 도메인만 켤 수 있게 했고, 동기 응답과 SSE 스트리밍을 함께 지원했습니다. 응답 JSON 파싱은 AiJsonSupport로 공통화했습니다. 그 결과 한 도메인의 AI 기능 문제가 다른 도메인의 수동 콘텐츠 관리에 영향을 주지 않도록 분리할 수 있었습니다.',0),(36,21,'PayApp에서 Ko-fi로 후원 결제 채널 전환',4,'초기에 PayApp 기반으로 구현했던 후원 결제 연동을 운영 중 Ko-fi 웹훅 방식으로 전환해야 했고, 기존 거래 식별자 저장 구조와 후원 이력을 유지한 채 전환해야 했습니다.',NULL,'- KofiWebhookController에서 verification-token으로 웹훅 요청을 검증\n- 기존 mul_no 컬럼을 Ko-fi 거래·메시지 ID 저장에 재사용하고 findWithLockByMulNo로 락을 걸어 중복 처리 방지\n- currency/is_subscription/provider_paid_at 컬럼을 추가해 다통화 및 구독 후원 지원(V63)\n- Spring Security 설정에서 웹훅 엔드포인트만 CSRF 예외 처리\n- PayApp 전용 컨트롤러·클라이언트 코드를 제거하고 Ko-fi 단일 채널로 정리','결제 채널을 Ko-fi로 완전히 전환하면서도 기존 도네이션 테이블과 이력을 유지했고, 웹훅 검증과 트랜잭션 단위 락으로 중복 후원 반영을 막았습니다.','PayApp 기반으로 구현했던 후원 결제 연동을 운영 중 Ko-fi 웹훅 방식으로 전환해야 했고, 기존 거래 식별자 저장 구조와 후원 이력은 그대로 유지해야 했습니다. KofiWebhookController에서 verification-token으로 웹훅을 검증하고, 기존 mul_no 컬럼을 Ko-fi 거래 ID 저장에 재사용하면서 findWithLockByMulNo로 락을 걸어 중복 처리를 막았습니다. currency·is_subscription·provider_paid_at 컬럼을 추가해 다통화와 구독 후원을 지원하고, 웹훅 엔드포인트만 CSRF 예외로 처리했습니다. PayApp 전용 코드는 완전히 제거하고 Ko-fi 단일 채널로 정리했습니다. 그 결과 결제 채널을 교체하면서도 기존 이력을 잃지 않고 중복 후원 반영을 방지할 수 있었습니다.',0),(37,21,'GitOps 기반 ARM64 컨테이너 배포 파이프라인 구축',2,'Oracle Cloud Free Tier의 ARM 기반 Kubernetes 클러스터에 백엔드와 프론트엔드를 배포해야 했고, 수동 배포 대신 코드 변경이 자동으로 클러스터 상태에 반영되는 구조가 필요했습니다.',NULL,'- GitHub Actions 워크플로우에서 QEMU/Buildx로 ARM64 이미지를 빌드해 OCI Registry(OCIR)에 커밋 SHA와 latest 태그로 푸시\n- sed로 Kustomize overlay의 이미지 태그를 갱신하고 그 변경을 main 브랜치에 다시 커밋\n- ArgoCD Application이 해당 커밋을 감지해 자동 sync·prune·self-heal 수행\n- 프로덕션 시크릿은 Bitnami Sealed Secrets로 암호화해 DB·AI·Ko-fi·스토리지 자격 증명 관리\n- Cloudflare를 API 및 ArgoCD 대시보드 앞단 프록시로 구성','코드가 main에 머지되면 이미지 빌드부터 매니페스트 갱신, 클러스터 동기화까지 사람 개입 없이 이어지는 배포 흐름을 구축했고, 시크릿을 평문 없이 저장소에 커밋할 수 있게 했습니다.','Oracle Cloud Free Tier의 ARM 기반 Kubernetes 클러스터에 백엔드와 프론트엔드를 배포하면서, 수동 배포 대신 코드 변경이 자동으로 반영되는 구조가 필요했습니다. GitHub Actions에서 QEMU/Buildx로 ARM64 이미지를 빌드해 OCIR에 푸시하고, sed로 Kustomize overlay의 이미지 태그를 갱신한 뒤 그 변경을 main에 다시 커밋했습니다. ArgoCD Application이 이 커밋을 감지해 자동으로 sync·prune·self-heal을 수행하도록 구성했고, 프로덕션 시크릿은 Sealed Secrets로 암호화해 저장소에 안전하게 커밋될 수 있게 했습니다. Cloudflare는 API와 ArgoCD 대시보드 앞단 프록시로 두었습니다. 그 결과 코드 머지부터 클러스터 반영까지 사람 개입 없이 이어지는 GitOps 배포 흐름을 완성했습니다.',1);
