INSERT INTO `profile` (`id`, `name`, `name_en`, `job_title`, `bio`, `core_stack_summary`, `status_badge_text`, `github_url`, `email`, `phone`, `updated_at`) VALUES (1,'신윤식','Yoonsik Shin','Software Engineer','소규모 스타트업 환경 속에서 데이터 모델링, 인프라 구축, 코드 컨벤션 정립, 레거시 리팩토링까지 백엔드 개발 전 사이클을 주도적으로 경험하며 문제 해결 역량을 다졌습니다. 특히 팀 내 코드 리뷰와 기술 공유를 통해 지식 격차를 줄이고 협업 효율을 높인 경험은 저의 큰 자산입니다.\n\n특정 언어에 국한되지 않고 보편적인 개발 원칙과 아키텍처를 학습·적용하며, 주어진 상황 속에서 최적의 해결책을 찾아내는 개발자를 지향합니다. 앞으로도 성능과 확장성이라는 핵심 가치를 중심으로 더 큰 규모의 시스템에 도전하며, 안정적이고 성장 가능한 서비스 구현에 기여하겠습니다.','Java / Node.js / AWS','실시간 아키텍처 및 콘텐츠 개선 중','https://github.com/Yoonsik-Shin','','','2026-07-15 17:08:44');
